def find_topmost_carpet(n, carpets, point) -> int:
    def get_carpet_boundaries(carpet):
        bottom_left, right_bottom, top_left, top_right = carpet
        return (bottom_left[0], bottom_left[1]), 
                (right_bottom[0], bottom_right[1]),
                (top_left[0], top_left[1]),
                (top_right[0], top_right[1])

    def is_within_carpet(carpet, query):
        boundaries = get_carpet_boundaries(carpet)
        bottom_left, right_bottom, top_left, top_right = boundaries
        x, y = query
        return x >= bottom_left[0] and x <= right_bottom[0] and y >= top_left[1] and y <= top_right[1]

    for i in range(n):
        if is_within_carpet(carpets[i], point):
            return i + 1  # Return 1-based index

    return -1

