def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    row, col = N, N
    dp = [[0] * col for _ in range(row)]

    # Fill the bottom-right corner of dp with grid_values
    for value in grid_values[::-1]:
        if value[0] == col - 1 and value[1] == row - 1:
            dp[row - 1][col - 1] = value[2]
            break

    # Fill the last column
    for i in range(row - 2, -1, -1):
        dp[i][col - 1] = dp[i + 1][col - 1] + grid_values[i][2]

    # Fill the last row
    for j in range(col - 2, -1, -1):
        dp[row - 1][j] = dp[row - 1][j + 1] + grid_values[row - 1][j]

    # Fill the rest of the dp table
    for i in range(row - 2, -1, -1):
        for j in range(col - 2, -1, -1):
            dp[i][j] = max(dp[i + 1][j], dp[i][j + 1]) + grid_values[i][2]

    return dp[0][0]

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize a DP table
    dp = [[0] * N for _ in range(N)]

    # Position of the last k elements in the first row
    last_k_positions = [0] * N

    # Populate the DP table from the bottom-right corner
    for row_idx, (x, y, value) in enumerate(grid_values[::-1]):
        last_k_positions.x = y
        last_k_positions.val = value
        for col_idx in range(y, -1, -1):
            if col_idx == last_k_positions.x:
                # Leftmost element, it has no left value so include the previous max
                dp[row_idx][col_idx] = dp[row_idx + 1][col_idx] + value
            elif not last_k_positions.x == 0:
                # Not the leftmost element
                dp[row_idx][col_idx] = max(dp[row_idx + 1][col_idx], dp[row_idx + 1][col_idx + 1]) + value

    # The maximum values from top-left to bottom-right corners
    return max(dp[0][col_idx] for col_idx in range(N))

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    if N == 0:
        return 0

    # Initialize the dp array with zeros
    dp = [[0] * N for _ in range(N)]

    # Map the grid_values to the dp array
    for x, y, value in grid_values:
        if (x, y) != (0, 0):
            dp[x][y] = value

    # Fill the dp array
    for i in range(1, N):
        for j in range(1, N):
            dp[i][j] += max(dp[i - 1][j], dp[i][j - 1])

    # The top-right corner of the dp array contains the maximum value
    top_right = dp[N - 1][N - 1]

    # The maximum value of the two paths could be in the top-left or bottom-right corners
    # or the sum of the two maximum values in the grid
    max_two_paths = max(top_right, sum(grid_values[0]) + sum(grid_values[-1]) - top_right)

    return max_two_paths

