def cantor_numbering(N: int) -> str:
    if N == 0:
        return '0/1'
    rest = N - 1
    level = 1
    while rest > 1:
        level += 1
        rest = (rest + level - 1) // level // 2
    position = (1 + rest) - level + 1
    if position % 2 == 0:
        numerator = level - (position + level - 2) // 2
        denominator = position + level - 1
    else:
        numerator = position + level - 1
        denominator = level - (position + level - 2) // 2
    if numerator > denominator:
        numerator, denominator = denominator, numerator
    return f"{numerator}/{denominator}"

