def max_product(num_str: str, N: int, K: int) -> int:
    # Convert the string to a list of integers for easier manipulation
    num_list = [int(digit) for digit in num_str]
    n = len(num_list)

    # Calculate the factorials of the digits
    factorials = []
    for digit in num_list:
        factorial = 1
        for i in range(1, digit + 1):
            factorial *= i
        factorials.append(factorial)

    # Calculate the product sums with K multiplication signs
    max_sum = 0
    for i in range(N + 1):
        for j in range(N + 1 - i):
            product_sum = 0
            for k in range(i + j + 1):
                if k == 0:
                    product_sum += factorials[k]
                elif k == i + j:
                    product_sum += factorials[k]
                else:
                    product_sum += factorials[k] / factorials[N - k]
            max_sum = max(max_sum, product_sum)

    # Round up the result to the nearest integer
    return max_sum

