import re

def verify_isbn(isbn: str) -> str:
    # Check the format of ISBN
    if not re.match(r'\d{9}(X?)$', isbn):
        return "Invalid Format"

    # Calculate the checksum
    digits = [int(d) if d.isdigit() or d == 'X' else 10 for d in isbn[:-1]]
    if isbn[-1].upper() == 'X':
        digits[-1] = 10
    checksum = 11 - sum(digits) % 11

    if checksum == 10:
        checksum = 'X'
    else:
        checksum = str(checksum)

    # Verify the calculated checksum
    if isbn[9] == checksum:
        return "Right"
    else:
        return isbn.replace(isbn[9], checksum)

