def count_passing_ways(n: int, m: int) -> int:
    if n == 1:
        return 1

    # Initialize the dp array
    dp = [0] * n
    dp[0] = 1  # There's one way to stay at the starting point with 1 pass

    # Dynamic programming initialization
    for k in range(2, m + 1):
        temp = dp.copy()
        dp[0] = temp[-1]  # Since the last element becomes the first after k passes
        for i in range(1, n):
            dp[i] = temp[i - 1] + temp[i + 1]

    return dp[0]

