        return 1

    # Initialize dynamic programming array
    dp = [[0 for _ in range(n)] for _ in range(m + 1)]

    # Base case: There's one way to stay at the same position after 0 passes
    dp[0][0] = 1

    # Fill the DP table
    for Passer in range(1, m + 1):
        for curr_student in range(n):
            for prev_student in range(n):
                # Calculate the number of ways to pass to the current student
                dp[Passer][curr_student] = dp[Passer][curr_student] + dp[Passer - 1][prev_student]

    return dp[m][0]

def count_passing_ways(n: int, m: int) -> int:
    if n == 1 or m == 0:
        return 1

    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        dp[i][0] = 1  # Starting and ending student can always pass the ball
        dp[0][i] = 1
        dp[i][i] = 1  # A circular arrangement where a student cannot pass to themselves

    for i in range(1, n):
        for j in range(1, m + 1):
            dp[i][j] = dp[i - 1][j - 1] + dp[i + 1][j - 1]

    return dp[n - 1][m]

