def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    durations = [v[0] for v in items]
    imp = [v[1] for v in items]

    # Create a DP table where dp[i][j] represents the maximum importance value
    # that can be achieved with a budget of i and considering the first j items
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if durations[j - 1] <= i:
                dp[i][j] = max(imp[j - 1] + dp[i - durations[j - 1]][j - 1], dp[i][j - 1])
            else:
                dp[i][j] = dp[i][j - 1]

    # The maximum value that can be achieved within the given budget
    return dp[n][m]

