def preorder_traversal(inorder: str, postorder: str) -> str:
    def create_node(val):
        return Node(val)

    class Node:
        def __init__(self, val):
            self.val = val
            self.left = None
            self.right = None

    def build_tree(inorder, postorder):
        stack = []
        root = create_node(postorder[-1])
        stack.append(root)
        for i in range(len(postorder) - 2, -1, -1):
            new_node = create_node(postorder[i])
            while stack and stack[-1].val > inorder[i]:
                node = stack.pop()
                node.right = new_node
            if stack:
                stack[-1].left = new_node
            stack.append(new_node)
        return root

    root = build_tree(inorder, postorder)
    def preorder(node):
        if node is None:
            return ""
        return node.val + preorder(node.left) + preorder(node.right)

    return preorder(root)

def preorder_traversal(inorder: str, postorder: str) -> str:
    def build_tree(inorder, postorder, start, end):
        if start > end:
            return None

        root_key = postorder[-1]
        root_index = inorder.find(root_key)

        new_tree = TreeNode(root_key)
        new_tree.left = build_tree(inorder, postorder, start, root_index - 1)
        new_tree.right = build_tree(inorder, postorder, root_index + 1, end)

        return new_tree

    def inorder_traversal_helper(node, result):
        if node is None:
            return

        preorder_traversal_helper(node.left, result)
        result.append(node.val)
        preorder_traversal_helper(node.right, result)

    root = build_tree(inorder, postorder, 0, len(inorder) - 1)
    result = []
    preorder_traversal_helper(root, result)
    return ''.join(str(i) for i in result)

