def generate_numbers(n: int, rules: List[Tuple[int, int]]) -> int:
    # Convert number to string and store it in a set to ensure uniqueness
    queue = deque([str(n)])
    seen = set(queue[0])

    while queue:
        current = queue.popleft()
        next_numbers = set()

        # Try each possible transformation
        for i in range(len(current)):
            for rule in rules:
                if current[i] == rule[0]:
                    next_number = current[:i] + str(rule[1]) + current[i + 1:]
                    if next_number not in seen:
                        next_numbers.add(next_number)
                        seen.add(next_number)
                        queue.append(next_number)

    return len(seen)

