def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize a table with the first row and column filled with 0
    dp = [[0] * (T + 1) for _ in range(M + 1)]

    # Fill the table using dynamic programming
    for i in range(1, M + 1):
        time = herbs[i - 1][0]
        value = herbs[i - 1][1]
        for j in range(1, T + 1):
            if j >= time:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - time] + value)
            else:
                dp[i][j] = dp[i - 1][j]

    # The maximum total value of herbs that can be picked within the time limit
    return dp[-1][-1]

