def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Create a DP table with dimensions (M+1) x (T+1)
    dp = [[0] * (T + 1) for _ in range(M + 1)]

    # Fill the DP table
    for herb_index in range(1, M + 1):
        for time in range(T + 1):
            # If the herb can be picked and does not exceed the time limit
            if herbs[herb_index - 1][0] <= time:
                # Select the maximum value between not picking the herb and picking it
                dp[herb_index][time] = max(dp[herb_index][time], herbs[herb_index - 1][1] + dp[herb_index - 1][time - herbs[herb_index - 1][0]])
            # If the herb cannot be picked or exceeds the time limit
            else:
                dp[herb_index][time] = dp[herb_index - 1][time]

    # The result is in dp[M][T]
    return dp[M][T]

