def mod_inverse(a, b):
    if b == 0:
        return None

    x0, x1 = 1, 0
    y0, y1 = 0, 1

    while b != 0:
        quotient = a // b
        a, b = b, a % b
        x0, x1 = x1, x0 - quotient * x1
        y0, y1 = y1, y0 - quotient * y1

    if a != 1:
        return None

    return x0 % b

