            if height_list[i] >= height_list[i + 1]:
                return False
        return True

    def is_descending(height_list):
        for i in range(len(height_list) - 1):
            if height_list[i] <= height_list[i + 1]:
                return False
        return True

    min_leave = 0
    for i in range(len(heights)):
        if is_descending(heights[:i + 1]):
            if is_ascending(heights[i + 1:]):
                min_leave += 1

    return min_leave

def minimum_students_to_leave(heights):
    if not heights:
        return 0

    start = 0
    end = len(heights) - 1

    while start < end:
        mid = (start + end) // 2

        if heights[mid + 1] > heights[mid]:
            start = mid + 1
        else:
            end = mid

    return len(heights) - start - 1

